"""Bundled Runtime Settings schema used by the Python Core.

Keep display metadata and validation constraints in importable Python data so
Runtime Settings works identically in a portable Core bundle.
"""

from __future__ import annotations

from datetime import datetime, timezone
import math
from typing import Final


RELAY_NEGATIVE_BALANCE_INTERVAL_KEY: Final = "YOUNG_ROUTER_RELAY_NEGATIVE_BALANCE_REFRESH_INTERVAL_MINUTES"
RELAY_NEGATIVE_BALANCE_DEFAULT_MINUTES: Final = 5
RELAY_SIGNED_IN_BALANCE_INTERVAL_KEY: Final = "YOUNG_ROUTER_RELAY_SIGNED_IN_BALANCE_REFRESH_INTERVAL_MINUTES"
RELAY_SIGNED_IN_BALANCE_DEFAULT_MINUTES: Final = 30


def relay_balance_observation_epoch(observed_at: object) -> float | None:
    """Read the same timezone-qualified balance stamp in Core and the proxy."""
    if not isinstance(observed_at, str) or not observed_at.strip():
        return None
    try:
        stamp = datetime.fromisoformat(observed_at.strip().replace("Z", "+00:00"))
        return stamp.timestamp() if stamp.tzinfo is not None else None
    except (ValueError, OverflowError):
        return None


def relay_balance_should_block(
    balance: object,
    observed_at: object,
    interval_minutes: object,
    *,
    now: datetime | None = None,
) -> bool:
    """Return whether a fresh negative balance should be excluded by routing."""

    if isinstance(balance, bool) or not isinstance(balance, (int, float)) or not balance < 0:
        return False
    if isinstance(balance, float) and not math.isfinite(balance):
        return False
    stamp = relay_balance_observation_epoch(observed_at)
    if stamp is None or isinstance(interval_minutes, bool):
        return False
    try:
        minutes = float(interval_minutes)
    except (TypeError, ValueError, OverflowError):
        return False
    if not math.isfinite(minutes) or minutes <= 0:
        return False
    age = (now or datetime.now(timezone.utc)).timestamp() - stamp
    return 0 <= age < minutes * 60.0


